function handle(action,value,btn){
 if(action==='lang'&&codes.includes(value)){if('speechSynthesis' in window)speechSynthesis.cancel();lang=value;save();mount();return}
 if(action==='exam'&&(value==='172'||value==='371'||value==='372')){exam=Number(value);idx=0;fresh();mount();return}
 if(action==='index'||action==='prev'||action==='next'){var next=action==='index'?Number(value):idx+(action==='next'?1:-1);if(Number.isInteger(next)&&next>=0&&next<Q.filter(function(x){return x.exam===exam}).length){idx=next;fresh();mount();document.getElementById('b3-question').setAttribute('tabindex','-1');document.getElementById('b3-question').focus()}return}
 if(action==='hint'){hints=Math.min(2,hints+1);mount();return}
 if(action==='step'){step=Math.min(3,step+1);mount();return}
 if(action==='reset'){idx=0;exam=371;fresh();mount();return}
 if(action==='stop'){stopRead();return}
 if(action==='tutor'){stopRead();try{if(window.TUTOR)TUTOR.open()}catch(e){}return}
 if(action==='say'){var sp=btn&&btn.parentElement?btn.parentElement.querySelector('.b3-tx'):null;if(sp)speakSegs([sp]);return}
 if(action==='read'){readAll();return}
 if(action==='pick'){if(correct)return;var v=Number(value),q2=item();
  if(Math.abs(v-q2.answer)<1e-9){correct=true;feedback=t('good')}else{picked=v;feedback=t('tryAgain')}
  mount();return}
 if(action==='check'){var input=document.getElementById('b3-answer'),raw=input.value.trim().replace(',','.');var num=/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw)?Number(raw):NaN;
  if(!Number.isFinite(num))feedback=t('invalid');else if(Math.abs(num-item().answer)<1e-9){feedback=t('good');correct=true}else feedback=t('tryAgain');
  var box=document.getElementById('b3-feedback');box.textContent=feedback;box.dataset.correct=correct?'true':'false';if(!correct)input.focus();return}
}
document.addEventListener('click',function(ev){var b=ev.target.closest('[data-b3]');if(!b||b.disabled)return;ev.preventDefault();ev.stopImmediatePropagation();handle(b.dataset.b3,b.dataset.value,b)} ,true);
document.addEventListener('keydown',function(ev){if(ev.target.id==='b3-answer'&&ev.key==='Enter'){ev.preventDefault();handle('check')}},true);
